const msgText = $('Telegram Trigger').item.json.message.text || '';
const routing = $json;
const today = $now.toFormat('yyyy-MM-dd');
let context;
if (/^\/wake\b/i.test(msgText.trim())) {
  context = "SYSTEM: Mark sent /wake. Follow the /wake command instructions.";
} else if (/^\/skip\b/i.test(msgText.trim())) {
  context = "SYSTEM: Mark sent /skip. Follow the /skip command instructions.";
} else if (/^\/testwake\b/i.test(msgText.trim())) {
  context = "SYSTEM: Mark sent /testwake. Follow the /testwake command instructions.";
} else {
  context = 'Mark\'s reply to grade (attempt ' + (routing.attempt || 1) + '): "' + msgText + '"';
}
return [{ json: { context, mode: 'reply', attempt: routing.attempt || 1, reply_text: msgText, log_date: today } }];

const today = $now.toFormat('yyyy-MM-dd');
const context = "SYSTEM: Generate and send today's Wake Proof passage now. Follow the Generating a passage instructions.";
return [{ json: { context, mode: 'passage', log_date: today } }];

const msgText = $('Telegram Trigger').item.json.message.text || '';
const history = $json.items || $json || [];
let historyBlock = '';
if (Array.isArray(history) && history.length > 0) {
  const lines = history.map(h => (h.role === 'user' ? 'Mark' : 'You') + ': ' + h.content);
  historyBlock = 'Recent conversation (oldest to newest, for context only - the newest message below is the actual instruction):\n' + lines.join('\n') + '\n\n';
}
const context = historyBlock + msgText;
return [{ json: { context, raw_user_text: msgText } }];

const items = $json.items;
const fmt12 = t => {
  if (!t) return '';
  const [hStr, m] = t.split(':');
  let h = parseInt(hStr, 10);
  const ampm = h >= 12 ? 'pm' : 'am';
  h = h % 12; if (h === 0) h = 12;
  return m === '00' ? (h + ampm) : (h + ':' + m + ampm);
};
const lines = items.map(it => {
  const time = it.end_time ? (fmt12(it.start_time) + '-' + fmt12(it.end_time)) : fmt12(it.start_time);
  const place = it.place ? (' · ' + it.place) : '';
  return '*' + it.title + '*, ' + time + place + ': done? \u2705 or tell me what happened';
});
return [{ json: { text: lines.join('\n') } }];

const m = $json.minutes;
const h = Math.floor(m / 60);
const mm = m % 60;
const label = h > 0 ? (h + 'h ' + mm + 'm') : (mm + 'm');
return [{ json: { text: 'TikTok: ' + label + ' straight so far' } }];

const d = $json;
const g = d.game || {};
const lvl = g.level != null ? 'Level ' + g.level : '';
const title = g.title ? g.title + ' · ' : '';
const xp = Math.round(g.total_xp || 0);
const streak = g.streak != null ? g.streak : 0;
const metrics = (d.metrics || []).map(m => {
  const val = m.unit === 'dollars' ? '$' + m.value : (m.unit === 'hours' ? m.value + 'h' : m.value);
  const prev = m.prev != null ? ' (prev ' + (m.unit === 'dollars' ? '$' + m.prev : (m.unit === 'hours' ? m.prev + 'h' : m.prev)) + ')' : '';
  return m.label + ': ' + val + prev;
}).join(' · ');
const titlesThisWeek = (g.titles || []).filter(t => t.earned && t.earned_on && t.earned_on >= d.from).map(t => t.name);
const titleLine = titlesThisWeek.length ? ('\nNew titles: ' + titlesThisWeek.join(', ')) : '';
const text = 'Start Up Ops · this week\n' + title + lvl + ' · ' + xp + ' XP · Streak ' + streak + '\n' + (metrics || '(nothing logged)') + titleLine;
return [{ json: { text } }];

